import { useCallback, useEffect, useState } from 'react'
import type { ExpenseViewModel, NewExpense, SubmitExpenseResult } from '../../application/ExpenseViewModel'
import { useExpensesUseCases } from '../useExpensesUseCases/useExpensesUseCases'

export const useExpenses = () => {
  const { listExpenses, submitExpense } = useExpensesUseCases()
  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)

  const load = useCallback(async () => {
    try {
      setExpenses(await listExpenses.execute())
      setLoadError(null)
    } catch (error) {
      setLoadError(error instanceof Error ? error.message : 'Could not load expenses')
    } finally {
      setLoading(false)
    }
  }, [listExpenses])

  useEffect(() => {
    void load()
  }, [load])

  const submit = async (expense: NewExpense): Promise<SubmitExpenseResult> => {
    const result = await submitExpense.execute(expense)
    if (result.kind === 'submitted') await load()
    return result
  }

  return { expenses, loading, loadError, submit }
}
